1	//! The palette: a popover, opened with Ctrl/Cmd+P, for fuzzy searching the
2	//! project's files, the application's own commands, and the harness's
3	//! commands, skills, and agents, each under its own tab. Picking a result
4	//! closes the palette and hands what was picked to the main window.
5	
6	use std::borrow::Cow;
7	use std::ops::Range;
8	use std::path::{Path, PathBuf};
9	
10	use gpui_kit::assets::IconName;
11	use gpui_kit::component::command::{Command, CommandItem, CommandState};
12	use gpui_kit::component::input::{IndentInline, OutdentInline};
13	use gpui_kit::component::kbd::Kbd;
14	use gpui_kit::component::tab::{Tab, TabBar};
15	use gpui_kit::component::{
16	    ActiveTheme as _, Disableable as _, Icon, Sizable as _, WindowExt as _, h_flex, v_flex,
17	};
18	use gpui_kit::prelude::FluentBuilder as _;
19	use gpui_kit::*;
20	
21	use crate::app::Quit;
22	use crate::fuzzy;
23	use crate::harness_mentions::{self, Invocable, MentionKind};
24	use crate::project_directory::ProjectDirectory;
25	
26	/// The most results a tab lists.
27	const MAX_RESULTS: usize = 100;
28	
29	/// The most files read from a project.
30	const MAX_FILES: usize = 100_000;
31	
32	const WIDTH: Pixels = px(640.);
33	const MAX_LIST_HEIGHT: Pixels = px(420.);
34	
35	#[derive(Clone, Copy, Debug, PartialEq, Eq)]
36	enum PaletteTab {
37	    Files,
38	    System,
39	    Commands,
40	    Skills,
41	    Agents,
42	}
43	
44	impl PaletteTab {
45	    /// In the order they are shown, and Tab cycles them.
46	    const ALL: [Self; 5] = [
47	        Self::Files,
48	        Self::System,
49	        Self::Commands,
50	        Self::Skills,
51	        Self::Agents,
52	    ];
53	
54	    fn label(self) -> &'static str {
55	        match self {
56	            Self::Files => "Files",
57	            Self::System => "System",
58	            Self::Commands => "Commands",
59	            Self::Skills => "Skills",
60	            Self::Agents => "Agents",
61	        }
62	    }
63	
64	    fn placeholder(self) -> &'static str {
65	        match self {
66	            Self::Files => "Search files…",
67	            Self::System => "Search the application's commands…",
68	            Self::Commands => "Search the harness's commands…",
69	            Self::Skills => "Search skills…",
70	            Self::Agents => "Search agents…",
71	        }
72	    }
73	
74	    fn icon(self) -> IconName {
75	        match self {
76	            Self::Files => IconName::File,
77	            Self::System => IconName::Wrench,
78	            Self::Commands => IconName::SquareTerminal,
79	            Self::Skills => IconName::BookOpen,
80	            Self::Agents => IconName::Bot,
81	        }
82	    }
83	
84	    fn mention_kind(self) -> Option<MentionKind> {
85	        match self {
86	            Self::Files | Self::System => None,
87	            Self::Commands => Some(MentionKind::Command),
88	            Self::Skills => Some(MentionKind::Skill),
89	            Self::Agents => Some(MentionKind::Agent),
90	        }
91	    }
92	}
93	
94	/// The application's own commands.
95	#[derive(Clone, Copy, Debug, PartialEq, Eq)]
96	pub enum SystemCommand {
97	    OpenProject,
98	    Build,
99	    ToggleRawOutput,
100	    ToggleDarkMode,
101	    Quit,
102	}
103	
104	/// What the application's commands depend on, as of opening the palette.
105	#[derive(Clone, Copy, Debug)]
106	pub struct SystemState {
107	    pub raw_output_visible: bool,
108	    pub can_build: bool,
109	    pub dark: bool,
110	}
111	
112	impl SystemState {
113	    fn commands(self) -> Vec<Candidate> {
114	        let raw_output = if self.raw_output_visible {
115	            "Hide Raw Output"
116	        } else {
117	            "View Raw Output"
118	        };
119	        let theme = if self.dark { "Light mode" } else { "Dark mode" };
120	        [
121	            (SystemCommand::OpenProject, "Open Project…", true),
122	            (SystemCommand::Build, "Build", self.can_build),
123	            (SystemCommand::ToggleRawOutput, raw_output, true),
124	            (SystemCommand::ToggleDarkMode, theme, true),
125	            (SystemCommand::Quit, "Quit", true),
126	        ]
127	        .into_iter()
128	        .map(|(command, label, enabled)| Candidate::System {
129	            command,
130	            label: label.into(),
131	            enabled,
132	        })
133	        .collect()
134	    }
135	}
136	
137	/// Emitted when a result is picked.
138	#[derive(Debug, PartialEq)]
139	pub enum Picked {
140	    File(PathBuf),
141	    System(SystemCommand),
142	    /// A harness mention to insert, as typed: `/name ` or `@agent-name `.
143	    Mention(String),
144	}
145	
146	#[derive(Clone, Debug)]
147	enum Candidate {
148	    File {
149	        path: PathBuf,
150	        /// The path in the project, with `/` between folders.
151	        label: SharedString,
152	        /// Byte offset of the file's name in `label`.
153	        name_start: usize,
154	    },
155	    System {
156	        command: SystemCommand,
157	        label: SharedString,
158	        enabled: bool,
159	    },
160	    Mention(Invocable),
161	}
162	
163	impl Candidate {
164	    fn text(&self) -> &str {
165	        match self {
166	            Self::File { label, .. } | Self::System { label, .. } => label,
167	            Self::Mention(invocable) => &invocable.name,
168	        }
169	    }
170	
171	    fn name_start(&self) -> usize {
172	        match self {
173	            Self::File { name_start, .. } => *name_start,
174	            _ => 0,
175	        }
176	    }
177	}
178	
179	/// A result as listed: the candidate and the byte offsets of its characters
180	/// the search matched.
181	struct Shown {
182	    candidate: Candidate,
183	    positions: Vec<usize>,
184	}
185	
186	/// The candidates the query matches, best first, up to [`MAX_RESULTS`]. An
187	/// empty query keeps them in their order.
188	fn rank(query: &str, candidates: &[Candidate]) -> Vec<Shown> {
189	    let mut matched: Vec<(i32, &Candidate, Vec<usize>)> = candidates
190	        .iter()
191	        .filter_map(|candidate| {
192	            let found = fuzzy::fuzzy_match(query, candidate.text(), candidate.name_start())?;
193	            Some((found.score, candidate, found.positions))
194	        })
195	        .collect();
196	    if !query.trim().is_empty() {
197	        matched.sort_by(|(a_score, a, _), (b_score, b, _)| {
198	            b_score
199	                .cmp(a_score)
200	                .then_with(|| a.text().len().cmp(&b.text().len()))
201	                .then_with(|| a.text().cmp(b.text()))
202	        });
203	    }
204	    matched
205	        .into_iter()
206	        .take(MAX_RESULTS)
207	        .map(|(_, candidate, positions)| Shown {
208	            candidate: candidate.clone(),
209	            positions,
210	        })
211	        .collect()
212	}
213	
214	/// Every file under `root`, by its path in the project, leaving out `.git`
215	/// and whatever the project's `.gitignore` files ignore. Blocking.
216	fn list_files(root: &Path) -> Vec<Candidate> {
217	    let mut files: Vec<Candidate> = ignore::WalkBuilder::new(root)
218	        .hidden(false)
219	        .require_git(false)
220	        .filter_entry(|entry| entry.file_name() != ".git")
221	        .build()
222	        .filter_map(Result::ok)
223	        .filter(|entry| entry.file_type().is_some_and(|kind| kind.is_file()))
224	        .take(MAX_FILES)
225	        .filter_map(|entry| {
226	            let relative = entry.path().strip_prefix(root).ok()?;
227	            let label = relative
228	                .components()
229	                .map(|part| part.as_os_str().to_string_lossy())
230	                .collect::<Vec<_>>()
231	                .join("/");
232	            let name_start = label.rfind('/').map_or(0, |ix| ix + 1);
233	            Some(Candidate::File {
234	                path: entry.path().to_path_buf(),
235	                label: label.into(),
236	                name_start,
237	            })
238	        })
239	        .collect();
240	    files.sort_by_cached_key(|file| file.text().to_lowercase());
241	    files
242	}
243	
244	pub struct Palette {
245	    /// Tracks the palette's elements, so focus inside them means it is open.
246	    focus_handle: FocusHandle,
247	    /// Replaced when the tab changes, so the highlight starts on the first
248	    /// result rather than on the row it was on.
249	    command: Entity<CommandState>,
250	    tab: PaletteTab,
251	    query: SharedString,
252	    system: SystemState,
253	    project: Option<PathBuf>,
254	    /// `None` while they are read.
255	    files: Option<Vec<Candidate>>,
256	    invocables: Option<Vec<Invocable>>,
257	    shown: Vec<Shown>,
258	    _loads: Vec<Task<()>>,
259	}
260	
261	impl EventEmitter<Picked> for Palette {}
262	
263	impl Palette {
264	    /// A palette on the Files tab, reading the project's files and the
265	    /// harness's commands, skills, and agents in the background.
266	    pub fn new(system: SystemState, window: &mut Window, cx: &mut Context<Self>) -> Self {
267	        let project = ProjectDirectory::get(cx);
268	
269	        let mut loads = Vec::new();
270	        if let Some(root) = project.clone() {
271	            let read = cx.background_spawn(async move { list_files(&root) });
272	            loads.push(cx.spawn(async move |this, cx| {
273	                let files = read.await;
274	                this.update(cx, |this, cx| {
275	                    this.files = Some(files);
276	                    this.refresh(cx);
277	                })
278	                .ok();
279	            }));
280	        }
281	        let discover = cx.background_spawn({
282	            let project = project.clone();
283	            async move {
284	                let mut invocables = harness_mentions::discover(project.as_deref());
285	                invocables.sort_by_cached_key(|invocable| invocable.name.to_lowercase());
286	                invocables
287	            }
288	        });
289	        loads.push(cx.spawn(async move |this, cx| {
290	            let invocables = discover.await;
291	            this.update(cx, |this, cx| {
292	                this.invocables = Some(invocables);
293	                this.refresh(cx);
294	            })
295	            .ok();
296	        }));
297	
298	        let mut this = Self {
299	            focus_handle: cx.focus_handle(),
300	            command: cx.new(|cx| CommandState::new(window, cx)),
301	            tab: PaletteTab::Files,
302	            query: SharedString::default(),
303	            system,
304	            project,
305	            files: None,
306	            invocables: None,
307	            shown: Vec::new(),
308	            _loads: loads,
309	        };
310	        this.refresh(cx);
311	        this
312	    }
313	
314	    /// Shows `palette` in a dialog over the window, with focus in its search.
315	    pub fn open(palette: &Entity<Self>, window: &mut Window, cx: &mut App) {
316	        let content = palette.clone();
317	        window.open_dialog(cx, move |dialog, _, _| {
318	            let content = content.clone();
319	            dialog
320	                .w(WIDTH)
321	                .p_0()
322	                .close_button(false)
323	                .content(move |body, _, _| body.child(content.clone()))
324	        });
325	        let command = palette.read(cx).command.clone();
326	        command.update(cx, |command, cx| command.focus(window, cx));
327	    }
328	
329	    /// Whether the palette is open: focus is somewhere inside it.
330	    pub fn is_open(&self, window: &Window, cx: &App) -> bool {
331	        self.focus_handle.contains_focused(window, cx)
332	    }
333	
334	    /// What Esc does: clears the search, or closes the palette once the search
335	    /// is empty.
336	    pub fn cancel(&mut self, window: &mut Window, cx: &mut Context<Self>) {
337	        if self.command.read(cx).query(cx).is_empty() {
338	            window.close_dialog(cx);
339	        } else {
340	            self.command
341	                .update(cx, |command, cx| command.set_query("", window, cx));
342	        }
343	    }
344	
345	    #[cfg(test)]
346	    pub fn result_labels(&self) -> Vec<String> {
347	        self.shown
348	            .iter()
349	            .map(|shown| shown.candidate.text().to_string())
350	            .collect()
351	    }
352	
353	    fn candidates(&self) -> Cow<'_, [Candidate]> {
354	        match self.tab.mention_kind() {
355	            None if self.tab == PaletteTab::Files => {
356	                Cow::Borrowed(self.files.as_deref().unwrap_or_default())
357	            }
358	            None => Cow::Owned(self.system.commands()),
359	            Some(kind) => Cow::Owned(
360	                self.invocables
361	                    .iter()
362	                    .flatten()
363	                    .filter(|invocable| invocable.kind == kind)
364	                    .cloned()
365	                    .map(Candidate::Mention)
366	                    .collect(),
367	            ),
368	        }
369	    }
370	
371	    fn refresh(&mut self, cx: &mut Context<Self>) {
372	        let shown = rank(&self.query, &self.candidates());
373	        self.shown = shown;
374	        cx.notify();
375	    }
376	
377	    fn set_query(&mut self, query: &str, cx: &mut Context<Self>) {
378	        self.query = query.to_string().into();
379	        self.refresh(cx);
380	    }
381	
382	    fn set_tab(&mut self, tab: PaletteTab, window: &mut Window, cx: &mut Context<Self>) {
383	        if tab == self.tab {
384	            return;
385	        }
386	        self.tab = tab;
387	        let query = self.query.clone();
388	        self.command = cx.new(|cx| {
389	            let mut command = CommandState::new(window, cx);
390	            command.set_query(query, window, cx);
391	            command
392	        });
393	        self.command
394	            .update(cx, |command, cx| command.focus(window, cx));
395	        self.refresh(cx);
396	    }
397	
398	    /// Moves `step` tabs along, wrapping around.
399	    fn cycle(&mut self, step: isize, window: &mut Window, cx: &mut Context<Self>) {
400	        let count = PaletteTab::ALL.len() as isize;
401	        let ix = PaletteTab::ALL
402	            .iter()
403	            .position(|tab| *tab == self.tab)
404	            .unwrap_or(0) as isize;
405	        let next = PaletteTab::ALL[(ix + step).rem_euclid(count) as usize];
406	        self.set_tab(next, window, cx);
407	    }
408	
409	    fn pick(&mut self, row: usize, window: &mut Window, cx: &mut Context<Self>) {
410	        let Some(shown) = self.shown.get(row) else {
411	            return;
412	        };
413	        let picked = match &shown.candidate {
414	            Candidate::File { path, .. } => Picked::File(path.clone()),
415	            Candidate::System { enabled: false, .. } => return,
416	            Candidate::System { command, .. } => Picked::System(*command),
417	            Candidate::Mention(invocable) => Picked::Mention(invocable.mention()),
418	        };
419	        window.close_dialog(cx);
420	        cx.emit(picked);
421	    }
422	
423	    fn empty_text(&self) -> &'static str {
424	        let loading = match self.tab {
425	            PaletteTab::Files if self.project.is_none() => return "No project open",
426	            PaletteTab::Files => self.files.is_none(),
427	            PaletteTab::System => false,
428	            _ => self.invocables.is_none(),
429	        };
430	        if loading {
431	            "Loading…"
432	        } else if !self.query.trim().is_empty() {
433	            "No matches"
434	        } else {
435	            match self.tab {
436	                PaletteTab::Files => "No files",
437	                PaletteTab::Commands => "No commands",
438	                PaletteTab::Skills => "No skills",
439	                PaletteTab::Agents => "No agents",
440	                PaletteTab::System => "",
441	            }
442	        }
443	    }
444	}
445	
446	/// A result's row: its icon, its text with the matched characters
447	/// highlighted, and a description or shortcut when it has one.
448	fn item(shown: &Shown, icon: IconName, cx: &App) -> CommandItem {
449	    let theme = cx.theme();
450	    let muted = theme.muted_foreground;
451	    let highlight = HighlightStyle {
452	        color: Some(theme.primary),
453	        font_weight: Some(FontWeight::BOLD),
454	        ..HighlightStyle::default()
455	    };
456	    let text: SharedString = shown.candidate.text().to_string().into();
457	    let highlights: Vec<(Range<usize>, HighlightStyle)> = shown
458	        .positions
459	        .iter()
460	        .map(|&start| {
461	            let len = text[start..].chars().next().map_or(1, char::len_utf8);
462	            (start..start + len, highlight)
463	        })
464	        .collect();
465	    let description = match &shown.candidate {
466	        Candidate::Mention(invocable) => invocable.description.clone(),
467	        _ => None,
468	    };
469	    let enabled = !matches!(shown.candidate, Candidate::System { enabled: false, .. });
470	    let quit = matches!(
471	        shown.candidate,
472	        Candidate::System {
473	            command: SystemCommand::Quit,
474	            ..
475	        }
476	    );
477	
478	    CommandItem::new()
479	        .label(text.clone())
480	        .disabled(!enabled)
481	        .child(move |window, _| {
482	            h_flex()
483	                .flex_1()
484	                .min_w_0()
485	                .gap_2()
486	                .items_center()
487	                .child(
488	                    Icon::new(icon.clone())
489	                        .small()
490	                        .flex_none()
491	                        .text_color(muted),
492	                )
493	                .child(
494	                    div()
495	                        .flex_none()
496	                        .max_w(relative(0.6))
497	                        .truncate()
498	                        .child(StyledText::new(text.clone()).with_highlights(highlights.clone())),
499	                )
500	                .when_some(description.clone(), |row, description| {
501	                    row.child(
502	                        div()
503	                            .flex_1()
504	                            .min_w_0()
505	                            .truncate()
506	                            .text_color(muted)
507	                            .child(description),
508	                    )
509	                })
510	                .when(quit, |row| {
511	                    row.children(
512	                        Kbd::binding_for_action(&Quit, None, window).map(|kbd| kbd.ml_auto()),
513	                    )
514	                })
515	        })
516	}
517	
518	impl Render for Palette {
519	    fn render(&mut self, _: &mut Window, cx: &mut Context<Self>) -> impl IntoElement {
520	        let this = cx.entity().downgrade();
521	        let icon = self.tab.icon();
522	        let items: Vec<CommandItem> = self
523	            .shown
524	            .iter()
525	            .map(|shown| item(shown, icon.clone(), cx))
526	            .collect();
527	        let empty: SharedString = self.empty_text().into();
528	        let selected_tab = PaletteTab::ALL
529	            .iter()
530	            .position(|tab| *tab == self.tab)
531	            .unwrap_or(0);
532	
533	        let command = Command::new(&self.command)
534	            .bordered(false)
535	            // Results are fuzzy matched and ranked here instead.
536	            .filterable(false)
537	            .max_h(MAX_LIST_HEIGHT)
538	            .placeholder(self.tab.placeholder())
539	            .header({
540	                let this = this.clone();
541	                move |_, _, _| {
542	                    let this = this.clone();
543	                    TabBar::new("palette-tabs")
544	                        .selected_index(selected_tab)
545	                        .on_click(move |ix, window, cx| {
546	                            this.update(cx, |this, cx| {
547	                                this.set_tab(PaletteTab::ALL[*ix], window, cx)
548	                            })
549	                            .ok();
550	                        })
551	                        .children(PaletteTab::ALL.map(|tab| Tab::new().label(tab.label())))
552	                }
553	            })
554	            .items(items)
555	            .empty(move |_, _, cx| {
556	                div()
557	                    .py_6()
558	                    .w_full()
559	                    .text_center()
560	                    .text_sm()
561	                    .text_color(cx.theme().muted_foreground)
562	                    .child(empty.clone())
563	            })
564	            .on_query({
565	                let this = this.clone();
566	                move |query, _, cx| {
567	                    this.update(cx, |this, cx| this.set_query(query, cx)).ok();
568	                }
569	            })
570	            .on_confirm(move |ix, window, cx| {
571	                this.update(cx, |this, cx| this.pick(ix.row, window, cx))
572	                    .ok();
573	            });
574	
575	        let palette = v_flex()
576	            .id("palette")
577	            .track_focus(&self.focus_handle)
578	            .w_full()
579	            .overflow_hidden()
580	            // Tab and Shift+Tab switch tabs rather than reaching the search
581	            // field, which keeps focus.
582	            .capture_action(cx.listener(|this, _: &IndentInline, window, cx| {
583	                cx.stop_propagation();
584	                this.cycle(1, window, cx);
585	            }))
586	            .capture_action(cx.listener(|this, _: &OutdentInline, window, cx| {
587	                cx.stop_propagation();
588	                this.cycle(-1, window, cx);
589	            }))
590	            .child(command);
591	        // Lets UI tests find the palette; inert in normal builds.
592	        gpui_kit::TestSupportExt::test_support(palette)
593	    }
594	}
