596	#[cfg(test)]
597	mod tests {
598	    use std::fs;
599	    use std::path::{Path, PathBuf};
600	
601	    use super::{Candidate, MAX_RESULTS, list_files, rank};
602	
603	    fn file(label: &str) -> Candidate {
604	        Candidate::File {
605	            path: PathBuf::from(label),
606	            label: label.to_string().into(),
607	            name_start: label.rfind('/').map_or(0, |ix| ix + 1),
608	        }
609	    }
610	
611	    fn texts(query: &str, candidates: &[Candidate]) -> Vec<String> {
612	        rank(query, candidates)
613	            .into_iter()
614	            .map(|shown| shown.candidate.text().to_string())
615	            .collect()
616	    }
617	
618	    #[test]
619	    fn ranks_the_best_matches_first() {
620	        let files = [
621	            file("spec/scope/application/MainWindow.pi"),
622	            file("src/main_window.rs"),
623	            file("src/main.rs"),
624	            file("src/toolbar.rs"),
625	        ];
626	        assert_eq!(
627	            texts("main", &files)[..2],
628	            ["src/main.rs", "src/main_window.rs"]
629	        );
630	        assert_eq!(
631	            texts("mwin", &files),
632	            ["src/main_window.rs", "spec/scope/application/MainWindow.pi"]
633	        );
634	        assert_eq!(texts("zzz", &files), Vec::<String>::new());
635	        // An empty search keeps the order.
636	        assert_eq!(texts("", &files)[0], "spec/scope/application/MainWindow.pi");
637	
638	        let many: Vec<Candidate> = (0..MAX_RESULTS * 2)
639	            .map(|ix| file(&format!("f{ix}.rs")))
640	            .collect();
641	        assert_eq!(rank("", &many).len(), MAX_RESULTS);
642	        assert_eq!(rank("f", &many).len(), MAX_RESULTS);
643	    }
644	
645	    #[test]
646	    fn lists_files_by_path_leaving_out_ignored_ones() {
647	        let root = Path::new(env!("CARGO_MANIFEST_DIR")).join("target/palette-files-test");
648	        fs::remove_dir_all(&root).ok();
649	        for path in [
650	            "src/b.rs",
651	            "src/A.rs",
652	            ".claude/skills/x/SKILL.md",
653	            "build/out.txt",
654	            ".git/HEAD",
655	            "README.md",
656	        ] {
657	            let path = root.join(path);
658	            fs::create_dir_all(path.parent().unwrap()).unwrap();
659	            fs::write(path, "").unwrap();
660	        }
661	        fs::write(root.join(".gitignore"), "/build\n").unwrap();
662	
663	        let labels: Vec<String> = list_files(&root)
664	            .iter()
665	            .map(|file| file.text().to_string())
666	            .collect();
667	        assert_eq!(
668	            labels,
669	            [
