18	        self.done
19	    }
20	
21	    pub fn push_line(&mut self, line: String, cx: &mut Context<Self>) {
22	        self.lines.push(line);
23	        cx.notify();
24	    }
25	
26	    pub fn finish(&mut self, cx: &mut Context<Self>) {
27	        self.done = true;
28	        cx.notify();
29	    }
30	}
