//! Harness runs: the raw output of each run, shared between prompt mode, which
//! feeds it, and harness streams, which show it.

use gpui_kit::*;

/// The raw output of one harness run, one line per event, as it arrives.
pub struct HarnessRun {
    lines: Vec<String>,
    done: bool,
}

impl HarnessRun {
    pub fn lines(&self) -> &[String] {
        &self.lines
    }

    pub fn is_done(&self) -> bool {
        self.done
    }

    pub fn push_line(&mut self, line: String, cx: &mut Context<Self>) {
        self.lines.push(line);
        cx.notify();
    }

    pub fn finish(&mut self, cx: &mut Context<Self>) {
        self.done = true;
        cx.notify();
    }
}

/// The session's harness runs; observers hear when a new run starts.
#[derive(Default)]
pub struct HarnessRuns {
    latest: Option<Entity<HarnessRun>>,
}

impl Global for HarnessRuns {}

impl HarnessRuns {
    pub fn init(cx: &mut App) {
        cx.set_global(Self::default());
    }

    /// Starts a new run and makes it the latest.
    pub fn start(cx: &mut App) -> Entity<HarnessRun> {
        let run = cx.new(|_| HarnessRun {
            lines: Vec::new(),
            done: false,
        });
        cx.update_global::<Self, _>(|runs, _| runs.latest = Some(run.clone()));
        run
    }

    /// The run still streaming, if any.
    pub fn in_progress(cx: &App) -> Option<Entity<HarnessRun>> {
        cx.global::<Self>()
            .latest
            .clone()
            .filter(|run| !run.read(cx).is_done())
    }
}

