208	    /// A stream left open follows each run that starts, after the last one's
209	    /// output.
210	    #[gpui_kit::test]
211	    async fn follows_every_run_that_starts(cx: &mut TestAppContext) {
212	        cx.update(|cx| {
213	            gpui_kit::init(cx);
214	            HarnessRuns::init(cx);
