265	                }
266	            })
267	        });
268	
269	        let editor = stream.read_with(cx, |stream, _| stream.editor.clone());
270	        let attached = stream.read_with(cx, |stream, _| stream.run.is_some());
271	        assert!(attached, "the stream did not follow the run that started");
272	
273	        let expected = lines
274	            .iter()
275	            .map(|line| pretty(line))
276	            .collect::<Vec<_>>()
277	            .join("\n\n");
278	        cx.wait_for(handle, Duration::from_secs(2), |_, cx| {
279	            editor.read(cx).value().len() == expected.len()
280	        })
