1	//! The main window of the application, from which all main functionality is
2	//! reached: a toolbar on top, and below it the project tree in a sidebar on the
3	//! left, then prompt mode with the harness stream split beside it while raw
4	//! output is shown.
5	
6	use gpui_kit::component::resizable::{ResizableState, h_resizable, resizable_panel};
7	use gpui_kit::component::{ActiveTheme, Root, WindowExt as _};
8	use gpui_kit::*;
9	
10	use crate::app::APP_TITLE;
11	use crate::harness_stream::HarnessStream;
12	use crate::palette::{Palette, Picked, SystemCommand, SystemState};
13	use crate::project_tree::{OpenFile, ProjectTree};
14	use crate::prompt_mode::PromptMode;
15	use crate::theme_preference;
16	use crate::toolbar::{self, RawOutputToggled, Toolbar};
17	
18	/// Size the window restores to when it is un-maximized.
19	const RESTORE_SIZE: Size<Pixels> = size(px(1280.), px(800.));
20	
21	/// The narrowest a split can be dragged.
22	const MIN_SPLIT_WIDTH: Pixels = px(240.);
23	
24	/// The sidebar's width until it is dragged, and the narrowest it can be.
25	const SIDEBAR_WIDTH: Pixels = px(260.);
26	const MIN_SIDEBAR_WIDTH: Pixels = px(160.);
27	
28	actions!(suspense, [FocusChat, TogglePalette]);
29	
30	/// Esc anywhere in the window moves focus to the chat input. It is bound
31	/// without a context, so an editor or popup that has something to cancel
32	/// (a completion menu, extra cursors) takes Esc first. Ctrl/Cmd+P opens or
33	/// closes the palette.
34	pub fn bind_keys(cx: &mut App) {
35	    cx.bind_keys([
36	        KeyBinding::new("escape", FocusChat, None),
37	        #[cfg(target_os = "macos")]
38	        KeyBinding::new("cmd-p", TogglePalette, None),
39	        #[cfg(not(target_os = "macos"))]
40	        KeyBinding::new("ctrl-p", TogglePalette, None),
41	    ]);
42	}
43	
44	pub struct MainWindow {
45	    toolbar: Entity<Toolbar>,
46	    sidebar: Entity<ProjectTree>,
47	    prompt_mode: Entity<PromptMode>,
48	    stream: Option<Entity<HarnessStream>>,
49	    /// The palette last opened, which may since have closed.
50	    palette: Option<Entity<Palette>>,
51	    _palette_subscription: Option<Subscription>,
52	    /// Kept apart from `splits` so the sidebar keeps its width when the
53	    /// stream split opens or closes.
54	    sidebar_split: Entity<ResizableState>,
55	    splits: Entity<ResizableState>,
56	    _subscriptions: Vec<Subscription>,
57	}
58	
59	impl MainWindow {
60	    pub fn open(cx: &mut App) -> Result<WindowHandle<Root>> {
61	        let options = WindowOptions {
62	            window_bounds: Some(WindowBounds::Maximized(Bounds::centered(
63	                None,
64	                RESTORE_SIZE,
65	                cx,
66	            ))),
67	            titlebar: Some(TitlebarOptions {
68	                title: Some(APP_TITLE.into()),
69	                ..Default::default()
70	            }),
71	            ..Default::default()
72	        };
73	
74	        cx.open_window(options, |window, cx| {
75	            // Start in the saved light or dark mode, else the system's; the
76	            // toolbar can switch.
77	            theme_preference::apply(window, cx);
78	            let view = cx.new(|cx| MainWindow::new(window, cx));
79	            cx.new(|cx| Root::new(view, window, cx))
80	        })
81	    }
82	
83	    pub fn new(window: &mut Window, cx: &mut Context<Self>) -> Self {
84	        let toolbar = cx.new(Toolbar::new);
85	        let sidebar = cx.new(ProjectTree::new);
86	        let subscriptions = vec![
87	            cx.subscribe_in(
88	                &toolbar,
89	                window,
90	                |this, _, event: &RawOutputToggled, window, cx| {
91	                    this.show_stream(event.visible, window, cx)
92	                },
93	            ),
94	            cx.subscribe_in(&sidebar, window, |this, _, OpenFile(path), window, cx| {
95	                this.prompt_mode.update(cx, |prompt_mode, cx| {
96	                    prompt_mode.open_file(path.clone(), window, cx)
97	                })
98	            }),
99	            // Until light or dark mode is chosen, the window keeps following
100	            // the system's appearance as it changes.
101	            cx.observe_window_appearance(window, |_, window, cx| {
102	                theme_preference::apply(window, cx)
103	            }),
104	            // Focus left on nothing, as when a focused file is closed, would
105	            // put Esc out of the window's reach; the chat input takes it.
106	            cx.on_focus_lost(window, |this, window, cx| {
107	                this.prompt_mode
108	                    .update(cx, |prompt_mode, cx| prompt_mode.focus_chat(window, cx))
109	            }),
110	        ];
111	
112	        Self {
113	            toolbar,
114	            sidebar,
115	            prompt_mode: cx.new(|cx| PromptMode::new(window, cx)),
116	            stream: None,
117	            palette: None,
118	            _palette_subscription: None,
119	            sidebar_split: cx.new(|_| ResizableState::default()),
120	            splits: cx.new(|_| ResizableState::default()),
121	            _subscriptions: subscriptions,
122	        }
123	    }
124	
125	    fn show_stream(&mut self, visible: bool, window: &mut Window, cx: &mut Context<Self>) {
126	        self.stream = visible.then(|| cx.new(|cx| HarnessStream::new(window, cx)));
127	        // Fresh split sizes, so none are left over from a closed split.
128	        self.splits = cx.new(|_| ResizableState::default());
129	        cx.notify();
130	    }
131	
132	    /// Opens a fresh palette on the Files tab, or closes the one open.
133	    fn toggle_palette(&mut self, window: &mut Window, cx: &mut Context<Self>) {
134	        if let Some(palette) = &self.palette
135	            && palette.read(cx).is_open(window, cx)
136	        {
137	            window.close_dialog(cx);
138	            return;
139	        }
140	        let toolbar = self.toolbar.read(cx);
141	        let system = SystemState {
142	            raw_output_visible: toolbar.raw_output_visible(),
143	            can_build: toolbar.can_build(cx),
144	            dark: cx.theme().is_dark(),
145	        };
146	        let palette = cx.new(|cx| Palette::new(system, window, cx));
147	        self._palette_subscription = Some(cx.subscribe_in(
148	            &palette,
149	            window,
150	            |this, _, picked: &Picked, window, cx| this.run_picked(picked, window, cx),
151	        ));
152	        Palette::open(&palette, window, cx);
153	        self.palette = Some(palette);
154	    }
155	
156	    fn run_picked(&mut self, picked: &Picked, window: &mut Window, cx: &mut Context<Self>) {
157	        match picked {
158	            Picked::File(path) => self.prompt_mode.update(cx, |prompt_mode, cx| {
159	                prompt_mode.open_file(path.clone(), window, cx)
160	            }),
161	            Picked::Mention(mention) => self.prompt_mode.update(cx, |prompt_mode, cx| {
162	                prompt_mode.insert_mention(mention, window, cx)
163	            }),
164	            Picked::System(command) => match command {
165	                SystemCommand::OpenProject => self
166	                    .toolbar
167	                    .update(cx, |toolbar, cx| toolbar.pick_project(window, cx)),
168	                SystemCommand::Build => self
169	                    .toolbar
170	                    .update(cx, |toolbar, cx| toolbar.build(window, cx)),
171	                SystemCommand::ToggleRawOutput => self
172	                    .toolbar
173	                    .update(cx, |toolbar, cx| toolbar.toggle_raw_output(cx)),
174	                SystemCommand::ToggleDarkMode => {
175	                    toolbar::set_dark_mode(!cx.theme().is_dark(), window, cx)
176	                }
177	                SystemCommand::Quit => cx.quit(),
178	            },
179	        }
180	    }
181	}
182	
183	impl Render for MainWindow {
184	    fn render(&mut self, window: &mut Window, cx: &mut Context<Self>) -> impl IntoElement {
185	        div()
186	            .size_full()
187	            .flex()
188	            .flex_col()
189	            .bg(cx.theme().background)
190	            .text_color(cx.theme().foreground)
191	            .on_action(cx.listener(|this, _: &FocusChat, window, cx| {
192	                // The context-less Esc binding outranks the palette's own, so
193	                // the palette's Esc is handled here.
194	                if let Some(palette) = &this.palette
195	                    && palette.read(cx).is_open(window, cx)
196	                {
197	                    palette.update(cx, |palette, cx| palette.cancel(window, cx));
198	                    return;
199	                }
200	                this.prompt_mode
201	                    .update(cx, |prompt_mode, cx| prompt_mode.focus_chat(window, cx))
202	            }))
203	            .on_action(
204	                cx.listener(|this, _: &TogglePalette, window, cx| this.toggle_palette(window, cx)),
205	            )
206	            .child(self.toolbar.clone())
207	            .child(
208	                div().flex_1().min_h_0().child(
209	                    // One `children` call for every panel: the group's
210	                    // `children` replaces panels added before it.
211	                    h_resizable("sidebar-split")
212	                        .with_state(&self.sidebar_split)
213	                        .children([
214	                            resizable_panel()
215	                                .size(SIDEBAR_WIDTH)
216	                                .size_range(MIN_SIDEBAR_WIDTH..Pixels::MAX)
217	                                .child(self.sidebar.clone()),
218	                            resizable_panel()
219	                                .size_range(MIN_SPLIT_WIDTH..Pixels::MAX)
220	                                .child(
221	                                    h_resizable("body").with_state(&self.splits).children(
222	                                        std::iter::once(
223	                                            resizable_panel()
224	                                                .size_range(MIN_SPLIT_WIDTH..Pixels::MAX)
225	                                                .child(self.prompt_mode.clone()),
226	                                        )
227	                                        .chain(
228	                                            self.stream.iter().map(|stream| {
229	                                                let split = div()
230	                                                    .id("stream")
231	                                                    .size_full()
232	                                                    .child(stream.clone());
233	                                                resizable_panel()
234	                                                    .size_range(MIN_SPLIT_WIDTH..Pixels::MAX)
235	                                                    // Lets UI tests find the split; inert in normal builds.
236	                                                    .child(gpui_kit::TestSupportExt::test_support(
237	                                                        split,
238	                                                    ))
239	                                            }),
240	                                        ),
241	                                    ),
242	                                ),
243	                        ]),
244	                ),
245	            )
246	            // Inside the window's element tree, so actions such as
247	            // TogglePalette reach it from a focused dialog.
248	            .children(Root::render_dialog_layer(window, cx))
249	            .children(Root::render_notification_layer(window, cx))
250	    }
251	}
252	
253	#[cfg(test)]
254	mod tests {
255	    // Explicit imports: globbing `gpui_kit::*` would bring in GPUI's `test`
256	    // macro and shadow Rust's `#[test]`.
257	    use std::time::Duration;
258	
259	    use gpui_kit::component::Root;
260	    use gpui_kit::test::{TestAppContextExt as _, TestWindowExt as _};
261	    use gpui_kit::{AppContext as _, TestAppContext};
262	
263	    use super::MainWindow;
264	    use crate::harness_run::HarnessRuns;
265	    use crate::piton_syntax;
266	    use crate::project_directory::ProjectDirectory;
267	
268	    const TIMEOUT: Duration = Duration::from_secs(2);
269	
270	    /// The chat input has focus as soon as the window opens: a prompt typed
271	    /// and sent without clicking anywhere is sent, which without a project
272	    /// open shows a notification saying so.
273	    #[gpui_kit::test]
274	    async fn chat_input_is_focused_when_the_window_opens(cx: &mut TestAppContext) {
275	        cx.update(|cx| {
276	            gpui_kit::init(cx);
277	            piton_syntax::init();
278	            ProjectDirectory::init(cx);
279	            HarnessRuns::init(cx);
280	        });
281	        let window = cx.add_window(|window, cx| {
282	            let view = cx.new(|cx| MainWindow::new(window, cx));
283	            Root::new(view, window, cx)
284	        });
285	        let handle = window.into();
286	        cx.wait_for(handle, TIMEOUT, |window, _| {
287	            window.try_find("prompt-editor").is_some()
288	        })
289	        .await;
290	
291	        for key in "hello".chars() {
292	            cx.update_window(handle, |_, window, cx| window.input(&key.to_string(), cx))
293	                .unwrap();
294	            cx.run_until_parked();
295	        }
296	        #[cfg(target_os = "macos")]
297	        let send = "cmd-enter";
298	        #[cfg(not(target_os = "macos"))]
299	        let send = "ctrl-enter";
300	        cx.update_window(handle, |_, window, cx| window.press(send, cx))
301	            .unwrap();
302	
303	        cx.wait_for(handle, TIMEOUT, |window, _| {
304	            window.try_find("notification").is_some()
305	        })
306	        .await;
307	    }
308	
309	    /// The toolbar's raw output toggle splits a harness stream off to the
310	    /// right of prompt mode, inside the window, and closes it again.
311	    #[gpui_kit::test]
312	    async fn raw_output_toggle_shows_and_hides_the_stream(cx: &mut TestAppContext) {
313	        cx.update(|cx| {
314	            gpui_kit::init(cx);
315	            piton_syntax::init();
316	            ProjectDirectory::init(cx);
