320	            let view = cx.new(|cx| MainWindow::new(window, cx));
321	            Root::new(view, window, cx)
322	        });
323	        let handle = window.into();
324	
325	        cx.wait_for(handle, TIMEOUT, |window, _| {
326	            window.try_find("raw-output").is_some()
327	        })
328	        .await;
329	        cx.update_window(handle, |_, window, cx| window.click("raw-output", cx))
