341	                .unwrap();
342	        }
343	
344	        cx.update_window(handle, |_, window, cx| {
345	            window.render_frame(cx);
346	            let viewport = window.viewport_size();
347	            let send = window.find("send").bounds();
348	            let stream = window.find("stream").bounds();
349	            assert!(
350	                stream.left() >= send.right() && stream.size.width > gpui_kit::px(0.),
351	                "stream is not beside prompt mode (Send at {send:?}): {stream:?} in {viewport:?}"
352	            );
