357	        })
358	        .unwrap();
359	
360	        cx.update_window(handle, |_, window, cx| window.click("raw-output", cx))
361	            .unwrap();
362	        cx.wait_for(handle, TIMEOUT, |window, _| {
363	            window.try_find("stream").is_none()
364	        })
365	        .await;
366	    }
