368	    /// Clicking a file in the project tree opens it beside the chat history,
369	    /// taking 50% of the width; the chat input stays unsplit below both.
370	    #[gpui_kit::test]
371	    async fn clicking_a_file_opens_it_beside_the_chat_history(cx: &mut TestAppContext) {
372	        let dir = std::env::temp_dir().join(format!("suspense-open-file-{}", std::process::id()));
373	        let _ = std::fs::remove_dir_all(&dir);
374	        std::fs::create_dir_all(&dir).unwrap();
375	        std::fs::write(dir.join("notes.md"), "# Notes\n").unwrap();
376	
377	        cx.update(|cx| {
378	            gpui_kit::init(cx);
379	            piton_syntax::init();
380	            ProjectDirectory::init(cx);
381	            HarnessRuns::init(cx);
382	        });
383	        let window = cx.add_window(|window, cx| {
384	            let view = cx.new(|cx| MainWindow::new(window, cx));
385	            Root::new(view, window, cx)
386	        });
387	        let handle = window.into();
388	
389	        cx.update(|cx| ProjectDirectory::set(dir.clone(), cx));
390	        cx.wait_for(handle, TIMEOUT, |window, _| {
391	            window.try_find(("project-entry", 0usize)).is_some()
392	        })
393	        .await;
394	        cx.update_window(handle, |_, window, cx| {
395	            window.click(("project-entry", 0usize), cx)
396	        })
397	        .unwrap();
398	        cx.wait_for(handle, TIMEOUT, |window, _| {
399	            window.try_find("file-view").is_some()
400	        })
401	        .await;
402	        for _ in 0..3 {
403	            cx.run_until_parked();
404	            cx.update_window(handle, |_, window, cx| window.render_frame(cx))
405	                .unwrap();
406	        }
407	
408	        cx.update_window(handle, |_, window, cx| {
409	            window.render_frame(cx);
410	            let file = window.find("file-view").bounds();
411	            let history = window.find("history").bounds();
412	            let editor = window.find("prompt-editor").bounds();
413	            let send = window.find("send").bounds();
414	            let share = file.size.width / (file.size.width + history.size.width);
415	            assert!(
416	                (share - 0.5).abs() < 0.02,
417	                "file takes {share} of the width: {file:?} beside {history:?}"
418	            );
419	            assert!(
420	                history.left() >= file.right() - gpui_kit::px(1.),
421	                "history is not right of the file: {file:?} then {history:?}"
422	            );
423	            assert!(
424	                editor.top() >= file.bottom()
425	                    && editor.left() < file.right()
426	                    && send.right() > history.left(),
427	                "chat input (editor {editor:?}, Send {send:?}) is split with the file {file:?}"
428	            );
429	        })
430	        .unwrap();
431	
432	        cx.update_window(handle, |_, window, cx| window.click("close-file", cx))
433	            .unwrap();
434	        cx.wait_for(handle, TIMEOUT, |window, _| {
435	            window.try_find("file-view").is_none()
436	        })
437	        .await;
438	
439	        std::fs::remove_dir_all(&dir).ok();
440	    }
