442	    /// Esc in an open file moves focus back to the chat input, where typing
443	    /// then lands.
444	    #[gpui_kit::test]
445	    async fn escape_in_a_file_focuses_the_chat_input(cx: &mut TestAppContext) {
446	        let dir = std::env::temp_dir().join(format!("suspense-escape-{}", std::process::id()));
447	        let _ = std::fs::remove_dir_all(&dir);
448	        std::fs::create_dir_all(&dir).unwrap();
449	        std::fs::write(dir.join("notes.md"), "# Notes\n").unwrap();
450	
451	        cx.update(|cx| {
452	            gpui_kit::init(cx);
453	            piton_syntax::init();
454	            ProjectDirectory::init(cx);
455	            HarnessRuns::init(cx);
456	            super::bind_keys(cx);
457	        });
458	        let mut main = None;
459	        let window = cx.add_window(|window, cx| {
460	            let view = cx.new(|cx| MainWindow::new(window, cx));
461	            main = Some(view.clone());
462	            Root::new(view, window, cx)
463	        });
464	        let main = main.unwrap();
465	        let handle = window.into();
466	
467	        cx.update(|cx| ProjectDirectory::set(dir.clone(), cx));
468	        cx.wait_for(handle, TIMEOUT, |window, _| {
469	            window.try_find(("project-entry", 0usize)).is_some()
470	        })
