1	//! Prompt mode: prompts, compiled on demand from Piton, are sent to a local
2	//! coding harness as tasks, and each task's output is shown until it finishes.
3	//!
4	//! The latest task heads the view: its status as a coloured label, the hidden
5	//! anchor it was compiled from, and the compiled prompt the harness received.
6	//! Its output fills the space beneath, one table row per thing the harness
7	//! did (its text, each tool call, any error), with the kind of each as a
8	//! badge. A small row, always shown above the header, expands into a scrollable
9	//! accordion of every task sent, each of which opens onto its own output. A file opened
10	//! from the project tree splits the view, taking half of its width; the chat
11	//! input is never split.
12	//!
13	//! Prompts sent while the harness works wait in a queue, saved with the
14	//! project (see [`crate::prompt_queue`]), listed in the header under the task.
15	//!
16	//! Every task is saved with the project too (see [`crate::prompt_history`]),
17	//! and opening the project brings back the tasks sent before.
18	
19	use std::cell::Cell;
20	use std::path::{Path, PathBuf};
21	use std::rc::Rc;
22	
23	use anyhow::Result;
24	use futures::StreamExt as _;
25	use gpui_kit::assets::IconName;
26	use gpui_kit::base::ElementExt as _;
27	use gpui_kit::component::accordion::Accordion;
28	use gpui_kit::component::button::{Button, ButtonVariants as _};
29	use gpui_kit::component::label::Label;
30	use gpui_kit::component::notification::Notification;
31	use gpui_kit::component::resizable::{ResizableState, h_resizable, resizable_panel};
32	use gpui_kit::component::spinner::Spinner;
33	use gpui_kit::component::switch::Switch;
34	use gpui_kit::component::table::{Table, TableBody, TableCell, TableHead, TableHeader, TableRow};
35	use gpui_kit::component::tag::Tag;
36	use gpui_kit::component::text::{TextView, TextViewStyle};
37	use gpui_kit::component::{
38	    ActiveTheme as _, ColorName, Icon, Sizable as _, StyledExt as _, h_flex, v_flex,
39	};
