348	impl Reply {
349	    /// Folds a harness event into the reply. Returns an error to show when the
350	    /// run failed.
351	    fn apply(&mut self, event: HarnessEvent) -> Option<String> {
352	        match event {
353	            // Raw output goes to harness streams, not the task's output.
354	            HarnessEvent::Output(_) => {}
355	            HarnessEvent::TextStarted => self.parts.push(ReplyPart::Text(String::new())),
356	            HarnessEvent::TextDelta(delta) => match self.parts.last_mut() {
357	                Some(ReplyPart::Text(text)) => text.push_str(&delta),
358	                _ => self.parts.push(ReplyPart::Text(delta)),
359	            },
360	            HarnessEvent::ToolStarted { id, name } => self.parts.push(ReplyPart::Tool(ToolCall {
361	                id,
362	                name,
363	                summary: None,
364	                state: ToolState::Running,
365	            })),
366	            HarnessEvent::ToolInput { id, summary } => {
367	                if let Some(call) = self.tool_mut(&id) {
368	                    call.summary = Some(summary);
369	                }
370	            }
371	            HarnessEvent::ToolFinished { id, is_error } => {
372	                if let Some(call) = self.tool_mut(&id) {
373	                    call.state = if is_error {
374	                        ToolState::Failed
375	                    } else {
376	                        ToolState::Done
377	                    };
378	                }
379	            }
380	            HarnessEvent::Finished { is_error, result } => {
381	                self.done = true;
382	                self.settle_tools(if is_error {
383	                    ToolState::Failed
384	                } else {
385	                    ToolState::Done
386	                });
387	                if is_error {
388	                    return Some(if result.is_empty() {
389	                        "The harness reported an error.".into()
390	                    } else {
391	                        result
392	                    });
393	                }
394	                // Nothing streamed (e.g. an older harness): show the result.
395	                if !self.has_text() && !result.is_empty() {
396	                    self.parts.push(ReplyPart::Text(result));
397	                }
398	            }
399	            HarnessEvent::Failed(error) => {
400	                self.done = true;
401	                self.settle_tools(ToolState::Failed);
402	                return Some(error);
403	            }
404	        }
405	        None
406	    }
407	
408	    /// Gives tool calls still running when the run ended the state they ended
409	    /// in, so none is left reading "running".
410	    fn settle_tools(&mut self, state: ToolState) {
411	        for part in &mut self.parts {
412	            if let ReplyPart::Tool(call) = part
413	                && call.state == ToolState::Running
414	            {
415	                call.state = state;
416	            }
417	        }
418	    }
419	
420	    fn tool_mut(&mut self, tool_id: &str) -> Option<&mut ToolCall> {
421	        self.parts.iter_mut().rev().find_map(|part| match part {
422	            ReplyPart::Tool(call) if call.id == tool_id => Some(call),
423	            _ => None,
424	        })
425	    }
426	
427	    fn has_text(&self) -> bool {
428	        self.parts
429	            .iter()
430	            .any(|part| matches!(part, ReplyPart::Text(text) if !text.trim().is_empty()))
431	    }
432	
433	    /// The rows of the output table, in the order they happened. Text with
434	    /// nothing in it yet is left out. Rows only change or are added at the end
435	    /// as the reply streams, so a row keeps its index.
436	    fn rows(&self) -> Vec<OutputRow<'_>> {
437	        self.parts
438	            .iter()
