    /// nothing in it yet is left out. Rows only change or are added at the end
    /// as the reply streams, so a row keeps its index.
    fn rows(&self) -> Vec<OutputRow<'_>> {
        self.parts
            .iter()
            .filter_map(|part| match part {
                ReplyPart::Text(text) if text.trim().is_empty() => None,

