fn markdown_view(id: impl Into<ElementId>, text: &str, cx: &App) -> TextView {
    TextView::markdown(id, markdown::without_inline_code(text)).style(TextViewStyle {
        heading_base_font_size: cx.theme().font_size,
        ..TextViewStyle::default()
    })
}

/// `code` as a fenced markdown code block, its fence longer than any run of
/// backticks inside it.
fn code_block(language: &str, code: &str) -> String {
    let longest = code.split(|c| c != '`').map(str::len).max().unwrap_or(0);
    let fence = "`".repeat(longest.max(2) + 1);
    format!("{fence}{language}\n{code}\n{fence}")
}

