use std::path::{Path, PathBuf};
use std::rc::Rc;

use anyhow::Result;
use futures::StreamExt as _;
use gpui_kit::assets::IconName;
use gpui_kit::base::ElementExt as _;
use gpui_kit::component::accordion::Accordion;
